-    *ctnt++ = '^';
-    *ctnt = 0;
-    channel(data ,"%s\n", content);
-}
+static void
+xmlParserPrintFileContextInternal(xmlParserInputPtr input ,
+        xmlGenericErrorFunc channel, void *data ) {
+    /* Defensive: Avoid dereferencing potentially freed parser inputs.
+       In some error paths input buffers may be reallocated/freed while
+       __xmlRaiseError is active. To prevent heap-use-after-free, only print
+       the location (filename/line) and skip attempting to access the
